const j = $input.first().json;
const body = (j && j.body) || {};
return [{ json: {
  run_id: 'wf3-' + $execution.id,
  started_at: new Date().toISOString(),
  force: body.force === true || body.force === 'true'
}}];

const cfgRows = $('Read Config').all().map(i=>i.json).filter(r=>r.key);
const config = Object.fromEntries(cfgRows.map(r=>[r.key,String(r.value)]));
const force = $('Init Run').first().json.force === true;
const rows = $('Read Calendar').all().map(i=>i.json).filter(r=>r.post_id && r.status==='approved');
const now = DateTime.now();
const due = rows.filter(r=>{ if (force) return true; try { return DateTime.fromISO(String(r.publish_at)) <= now; } catch(e){ return false; } });
return due.map(r=>({json:{...r,
  publish_mode: config.publish_mode||'dry_run',
  ig_user_id: config.ig_user_id||'',
  graph_api_version: config.graph_api_version||'v25.0',
  ig_access_token: config.ig_access_token||''
}}));

const r = $json;
const v = r.graph_api_version; const ig = r.ig_user_id;
const base = 'https://graph.facebook.com/' + v + '/';
const caption = (r.caption_en + '\n\n' + r.caption_ar + '\n\n' + r.hashtags);
let seq = [];
if (r.format === 'reel') {
  seq = [
    {step:1, method:'POST', url: base+ig+'/media', payload:{media_type:'REELS', video_url:'<PUBLIC_HTTPS_VIDEO_URL>', caption, share_to_feed:true, access_token:'<TOKEN>'}},
    {step:2, method:'GET', url: base+'<CREATION_ID>?fields=status_code', note:'poll ~1/min up to 5 min until FINISHED; publishing while IN_PROGRESS returns error 9007'},
    {step:3, method:'POST', url: base+ig+'/media_publish', payload:{creation_id:'<CREATION_ID>', access_token:'<TOKEN>'}}
  ];
} else if (r.format === 'carousel') {
  seq = [
    {step:1, method:'POST', url: base+ig+'/media', payload:{image_url:r.image_url, is_carousel_item:true, access_token:'<TOKEN>'}, note:'repeat per child slide (2-10), collect child creation ids'},
    {step:2, method:'POST', url: base+ig+'/media', payload:{media_type:'CAROUSEL', children:'<CHILD_ID_1>,<CHILD_ID_2>,...', caption, access_token:'<TOKEN>'}},
    {step:3, method:'POST', url: base+ig+'/media_publish', payload:{creation_id:'<CAROUSEL_CONTAINER_ID>', access_token:'<TOKEN>'}}
  ];
} else {
  seq = [
    {step:1, method:'POST', url: base+ig+'/media', payload:{image_url:r.image_url, caption, alt_text:r.topic, access_token:'<TOKEN>'}},
    {step:2, method:'POST', url: base+ig+'/media_publish', payload:{creation_id:'<CREATION_ID>', access_token:'<TOKEN>'}}
  ];
}
const pre = {step:0, method:'GET', url: base+ig+'/content_publishing_limit?fields=quota_usage', note:'check quota_usage < 100 API posts per rolling 24h before publishing'};
return {json:{
  post_id: r.post_id,
  status: 'published',
  media_id: 'DRYRUN_' + r.post_id,
  published_at: new Date().toISOString(),
  api_payload_log: JSON.stringify({mode:'dry_run', sequence:[pre, ...seq]})
}};

const resp = $json;
const orig = $('Publish Mode?').item.json;
const quota = (resp.data && resp.data[0]) ? resp.data[0].quota_usage : null;
if (quota !== null && quota >= 100) throw new Error('Instagram publishing quota reached (100 posts / rolling 24h)');
return {json: orig};

const resp = $json;
let orig = {};
try { orig = $('Media Type?').item.json; } catch(e) {}
return {json:{
  post_id: orig.post_id || resp.post_id || '',
  status: resp.status === 'failed' ? 'failed' : 'published',
  media_id: resp.id || resp.media_id || '',
  published_at: new Date().toISOString(),
  api_payload_log: resp.api_payload_log || JSON.stringify({mode:'live', publish_response: resp})
}};

const items = $input.all().map(i=>i.json);
const init = $('Init Run').first().json;
const finished = new Date().toISOString();
const m = items.length ? String(items[0].post_id||'').match(/^b(\d+)-/) : null;
let mode = 'n/a';
try { mode = $('Select Due').first().json.publish_mode; } catch(e) {}
return [{json:{
  run_id: init.run_id, workflow:'WF3-publisher', batch_id: m ? m[1] : '',
  started_at: init.started_at, finished_at: finished,
  duration_s: String(Math.round((new Date(finished).getTime()-new Date(init.started_at).getTime())/1000)),
  llm_cost_usd:'', posts_count: String(items.length), cost_per_post_usd:'',
  notes: 'publish run, mode=' + mode
}}];
